return-response.set-body:
@{
                        return new JObject(
                            new JProperty("resourceType", "OperationOutcome"),
                            new JProperty("issue", new JArray(new JObject(
                                new JProperty("severity", "error"),
                                new JProperty("code", "forbidden"),
                                new JProperty("diagnostics", "Application " + (string)context.Variables["callerAppId"] + " is not authorised for inbound ingest. Payer-facing credentials cannot write.")
                            )))
                        ).ToString();
                    }

@{
                        return new JObject(
                            new JProperty("resourceType", "OperationOutcome"),
                            new JProperty("issue", new JArray(new JObject(
                                new JProperty("severity", "error"),
                                new JProperty("code", "forbidden"),
                                new JProperty("diagnostics", "$export is not available on the inbound ingest endpoint. Inbound and outbound are separately authorised routes over the same FHIR service.")
                            )))
                        ).ToString();
                    }

@{
                                return new JObject(
                                    new JProperty("resourceType", "OperationOutcome"),
                                    new JProperty("issue", new JArray(new JObject(
                                        new JProperty("severity", "error"),
                                        new JProperty("code", "required"),
                                        new JProperty("diagnostics", "Header X-Providence-Contract is required on all writes so the resource can be tagged for contract-level isolation.")
                                    )))
                                ).ToString();
                            }

when.set-body:
@{
                    var body = context.Request.Body.As<JObject>(preserveContent: true);
                    var contract = context.Request.Headers.GetValueOrDefault("X-Providence-Contract", "");
                    var meta = body["meta"] as JObject;
                    if (meta == null) { meta = new JObject(); body["meta"] = meta; }
                    var tags = meta["tag"] as JArray;
                    if (tags == null) { tags = new JArray(); meta["tag"] = tags; }
                    var already = tags.Any(t => t["system"] != null && t["system"].ToString() == "https://providence.org/fhir/contract");
                    if (!already) {
                        tags.Add(new JObject(
                            new JProperty("system", "https://providence.org/fhir/contract"),
                            new JProperty("code", contract)
                        ));
                    }
                    return body.ToString();
                }

on-error.set-body:
@{
            return new JObject(
                new JProperty("resourceType", "OperationOutcome"),
                new JProperty("issue", new JArray(new JObject(
                    new JProperty("severity", "error"),
                    new JProperty("code", "exception"),
                    new JProperty("diagnostics", context.LastError?.Message ?? "Gateway error"),
                    new JProperty("details", new JObject(new JProperty("text", "correlationId=" + context.RequestId)))
                )))
            ).ToString();
        }
